    @BeforeEach void setup(){base=new ExperienceMySqlTest();base.fixture();student=base.student;store=new RunStore(db,mapper,true,true);provider=new PublishedTaskContentProvider(db,repository,true,true);runs=new RunService(store,provider,base.idem,tx);version=provider.review(VERSION);execute=new ExecutionService(runs,new FixedExecutionCalculator(provider,mapper,new ClassifierEngine(repository,mapper)),mock(RateLimits.class));closure=new ClosurePipeline(runs);reflection=new ReflectionService(runs,closure);jobs=new EvidenceJobs(runs,closure);}
    @AfterEach void cleanup(){long id=student.internalId();db.update("DELETE FROM mp_ai_call WHERE student_id=?",id);db.update("DELETE FROM mp_background_job WHERE owner_student_id=?",id);db.update("DELETE FROM mp_report WHERE student_id=?",id);db.update("DELETE i FROM mp_evidence_item i JOIN mp_evidence_snapshot s ON s.id=i.evidence_snapshot_id WHERE s.student_id=?",id);db.update("DELETE FROM mp_evidence_snapshot WHERE student_id=?",id);db.update("UPDATE mp_recommendation SET source_run_id=NULL WHERE student_id=?",id);db.update("DELETE d FROM mp_recommendation_decision d JOIN mp_recommendation r ON r.id=d.recommendation_id WHERE r.student_id=? AND r.recommendation_type='NEXT'",id);db.update("DELETE reason FROM mp_recommendation_reason reason JOIN mp_recommendation r ON r.id=reason.recommendation_id WHERE r.student_id=? AND r.recommendation_type='NEXT'",id);db.update("DELETE FROM mp_recommendation WHERE student_id=? AND recommendation_type='NEXT'",id);
        // Original Run references INITIAL, so remove the Run tree before its decisions/profiles.
        cleanupRuns(id);
        db.update("DELETE d FROM mp_recommendation_decision d JOIN mp_recommendation r ON r.id=d.recommendation_id WHERE r.student_id=?",id);db.update("DELETE reason FROM mp_recommendation_reason reason JOIN mp_recommendation r ON r.id=reason.recommendation_id WHERE r.student_id=?",id);db.update("DELETE FROM mp_recommendation WHERE student_id=?",id);db.update("DELETE FROM mp_decision_answer WHERE decision_profile_id IN (SELECT id FROM mp_decision_profile WHERE student_id=?)",id);base.cleanup();db.update("UPDATE mp_task_version SET status='REVIEW' WHERE public_id=?",VERSION);
    }
    void cleanupRuns(long student){db.update("DELETE FROM mp_product_event WHERE student_id=?",student);db.update("DELETE FROM mp_idempotency_record WHERE owner_student_id=?",student);db.update("DELETE c FROM mp_step_completion c JOIN mp_step_state s ON s.id=c.step_state_id JOIN mp_experience_run r ON r.id=s.experience_run_id WHERE r.student_id=?",student);
        for(var row:db.queryForList("SELECT id,public_id FROM mp_experience_run WHERE student_id=? ORDER BY attempt_no DESC",student)){long id=((Number)row.get("id")).longValue();db.update("DELETE FROM mp_sensitive_audit WHERE target_public_id=?",row.get("public_id"));db.update("DELETE a FROM mp_reflection_answer a JOIN mp_reflection r ON r.id=a.reflection_id WHERE r.experience_run_id=?",id);db.update("DELETE FROM mp_reflection WHERE experience_run_id=?",id);db.update("DELETE FROM mp_hint_request WHERE experience_run_id=?",id);db.update("DELETE x FROM mp_response_execution x JOIN mp_execution_record e ON e.id=x.execution_record_id WHERE e.experience_run_id=?",id);db.update("DELETE FROM mp_execution_record WHERE experience_run_id=?",id);db.update("DELETE r FROM mp_step_response_revision r JOIN mp_step_state s ON s.id=r.step_state_id WHERE s.experience_run_id=?",id);db.update("DELETE FROM mp_step_state WHERE experience_run_id=?",id);db.update("DELETE FROM mp_run_closure_request WHERE experience_run_id=?",id);db.update("DELETE FROM mp_experience_run WHERE id=?",id);}}
    RunDtos.Run preview(){return runs.createPreview(student,key(),new RunDtos.CreatePreview(VERSION));}
    RunDtos.Run start(RunDtos.Run run){return runs.transition(student,run.runId(),"start",key(),new RunDtos.Transition(run.revision(),null,null));}
    RunDtos.Run current(RunDtos.Run run){return runs.get(student,run.runId());}
    JsonNode value(JsonNode schema,int index){if(schema.has("const"))return schema.get("const");if(schema.has("enum"))return schema.path("enum").get(index%schema.path("enum").size());return switch(schema.path("type").asText()){
        case "object"->{var node=mapper.createObjectNode();for(var field:schema.path("required"))node.set(field.asText(),value(schema.path("properties").path(field.asText()),0));yield node;}
        case "array"->{var node=mapper.createArrayNode();for(int i=0;i<schema.path("minItems").asInt();i++)node.add(value(schema.path("items"),i));yield node;}
        case "boolean"->BooleanNode.TRUE;case "number","integer"->IntNode.valueOf(schema.path("minimum").asInt());default->TextNode.valueOf("合成技术验证回答"+index);
    };}
    RunDtos.Saved save(RunDtos.Run run,String step,JsonNode answer){var view=runs.step(student,run.runId(),step);return runs.save(student,run.runId(),step,new RunDtos.Save(view.revision(),view.responseSchemaVersion(),answer));}
    RunDtos.Run complete(RunDtos.Run run,String step,JsonNode answer){var saved=save(run,step,answer);return runs.completeStep(student,run.runId(),step,key(),new RunDtos.Revision(saved.revision()));}
    JsonNode definition(String key){for(var step:version.manifest().path("steps"))if(step.path("stepKey").asText().equals(key))return step;throw new IllegalStateException();}
    ObjectNode config(double threshold){var node=(ObjectNode)value(definition("a4-configure").path("inputSchema"),0);node.put("confidenceThreshold",threshold);return node;}
    RunDtos.Run toEvaluation(RunDtos.Run ready){var run=start(ready);for(String key:List.of("a1-task","a2-metrics","a3-errors"))run=complete(run,key,value(definition(key).path("inputSchema"),0));run=complete(run,"a4-configure",config(.55));save(run,"a5-evaluate",mapper.createObjectNode());return current(run);}
    RunDtos.Execute request(RunDtos.Run run){return new RunDtos.Execute("ai-evaluate",runs.step(student,run.runId(),"a5-evaluate").revision(),mapper.createObjectNode(),null,null);}
    void reconfigure(RunDtos.Run run,ObjectNode configuration){var saved=save(run,"a4-configure",configuration);runs.completeStep(student,run.runId(),"a4-configure",key(),new RunDtos.Revision(saved.revision()));}
    RunDtos.Run toReflection(RunDtos.Run run){save(run,"a5-evaluate",value(definition("a5-evaluate").path("inputSchema"),0));execute.execute(student,run.runId(),key(),request(run));run=runs.completeStep(student,run.runId(),"a5-evaluate",key(),new RunDtos.Revision(runs.step(student,run.runId(),"a5-evaluate").revision()));run=complete(run,"a6-decision",value(definition("a6-decision").path("inputSchema"),0));return runs.taskComplete(student,run.runId(),key(),new RunDtos.Revision(run.revision()));}
    RunDtos.Run close(RunDtos.Run run){var view=reflection.get(student,run.runId());var answers=(ObjectNode)value(view.definition().path("inputSchema"),0);answers.put("nextWorkStyle","DATA_REASONING");return reflection.submit(student,run.runId(),key(),new RunDtos.ReflectionSave(view.revision(),view.questionSetVersion(),answers));}
    long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE student_id=?",Long.class,student.internalId());}
    @Test void previewRemainsPreviewAfterContentPublicationAndDoesNotOccupyStandardLane(){var preview=preview();var standard=formal();assertNotEquals(preview.runId(),standard.runId());assertEquals("STANDARD",standard.runMode());var active=start(preview);assertEquals("REVIEW_PREVIEW",active.runMode());var switched=runs.transition(student,standard.runId(),"start",key(),new RunDtos.Transition(standard.revision(),active.runId(),active.revision()));assertEquals("STANDARD",switched.runMode());assertEquals("PAUSED",current(preview).status());assertEquals("REVIEW_PREVIEW",current(preview).runMode());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_experience_run WHERE student_id=? AND active_guard=1",Integer.class,student.internalId()));}
    @Test void successfulNonBaselineQuotaAndSetNormalizationAreDurable(){var run=toEvaluation(preview());execute.execute(student,run.runId(),key(),request(run));var settings=List.of(config(.4),config(.7),config(.4).put("lowConfidencePolicy","AUTO_ROUTE"),config(.55).put("lowConfidencePolicy","AUTO_ROUTE"),config(.7).put("lowConfidencePolicy","AUTO_ROUTE"));for(int i=0;i<settings.size();i++){reconfigure(run,settings.get(i));assertEquals(4-i,execute.execute(student,run.runId(),key(),request(run)).remainingEvaluations());}var sixth=config(.55);((ObjectNode)sixth.path("definitionVariantIds")).put("technical_issue","technical-clarified");reconfigure(run,sixth);base.error("EVALUATION_LIMIT_REACHED",()->execute.execute(student,run.runId(),key(),request(run)));reconfigure(run,config(.55));var free=execute.execute(student,run.runId(),key(),request(run));assertEquals(0,free.remainingEvaluations());assertTrue(free.reused());}
