    @Test void currentA5RevisionCannotCompleteUsingAnOldA4Binding(){var run=toEvaluation(preview());save(run,"a5-evaluate",value(definition("a5-evaluate").path("inputSchema"),0));var first=execute.execute(student,run.runId(),key(),request(run));reconfigure(run,config(.4));var step=runs.step(student,run.runId(),"a5-evaluate");assertNull(step.executions().getFirst().appliedToRevision());assertNull(step.executions().getFirst().appliedSourceRevisions());base.error("EXECUTION_NOT_ALLOWED",()->runs.completeStep(student,run.runId(),"a5-evaluate",key(),new RunDtos.Revision(step.revision())));execute.execute(student,run.runId(),key(),request(run));assertDoesNotThrow(()->runs.completeStep(student,run.runId(),"a5-evaluate",key(),new RunDtos.Revision(step.revision())));}
    @Test void temporaryAccountLockDefersWorkWithoutCancellingEvidencePermanently(){close(toReflection(toEvaluation(preview())));var lease=jobs.claim("test-before-lock");var items=jobs.build(lease);db.update("UPDATE mp_student_account SET status='LOCKED' WHERE id=?",student.internalId());assertFalse(jobs.publish(lease,items));db.update("UPDATE mp_background_job SET lease_until=UTC_TIMESTAMP(3)-INTERVAL 1 SECOND WHERE id=?",lease.job());assertNull(jobs.claim("test-during-lock"));assertEquals("RETRY_WAIT",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,lease.job()));db.update("UPDATE mp_student_account SET status='ACTIVE' WHERE id=?",student.internalId());db.update("UPDATE mp_background_job SET available_at=UTC_TIMESTAMP(3) WHERE id=?",lease.job());var resumed=jobs.claim("test-after-lock");assertNotNull(resumed);jobs.process(resumed);assertEquals("READY",db.queryForObject("SELECT status FROM mp_evidence_snapshot WHERE id=?",String.class,resumed.snapshot()));}
