    @Test void baselineIsFreeAndReusedConfigurationKeepsOriginalAndCurrentSourceRevisions(){var run=toEvaluation(preview());var calculator=spy(new FixedExecutionCalculator(provider,mapper,new ClassifierEngine(repository,mapper)));var service=new ExecutionService(runs,calculator,mock(RateLimits.class));var baseline=service.execute(student,run.runId(),key(),request(run));assertEquals(5,baseline.remainingEvaluations());assertEquals(Map.of("a4-configure",1L),baseline.sourceRevisions());reconfigure(run,config(.4));var changed=service.execute(student,run.runId(),key(),request(run));assertEquals(4,changed.remainingEvaluations());reconfigure(run,config(.55));var reused=service.execute(student,run.runId(),key(),request(run));assertTrue(reused.reused());assertEquals(baseline.executionId(),reused.executionId());assertEquals(Map.of("a4-configure",1L),reused.sourceRevisions());assertEquals(Map.of("a4-configure",3L),reused.appliedSourceRevisions());verify(calculator,times(2)).calculate(any(),any(),any());var history=runs.step(student,run.runId(),"a5-evaluate").executions();assertEquals(3L,history.stream().filter(e->e.executionId().equals(baseline.executionId())).findFirst().orElseThrow().appliedSourceRevisions().get("a4-configure"));}
    @Test void terminalFenceRejectsSourceRevisionChangeEvenAfterDependencyRecompleted()throws Exception{var run=toEvaluation(preview());save(run,"a5-evaluate",value(definition("a5-evaluate").path("inputSchema"),0));var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var original=new FixedExecutionCalculator(provider,mapper,new ClassifierEngine(repository,mapper));var delayed=new ExecutionCalculator(){public JsonNode normalize(TaskContent.Version v,JsonNode o,JsonNode p){return original.normalize(v,o,p);}public JsonNode calculate(TaskContent.Version v,JsonNode o,JsonNode p){assertFalse(TransactionSynchronizationManager.isActualTransactionActive());entered.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}return original.calculate(v,o,p);}};var service=new ExecutionService(runs,delayed,mock(RateLimits.class));var request=request(run);try(var pool=Executors.newSingleThreadExecutor()){var result=pool.submit(()->assertThrows(ApiException.class,()->service.execute(student,run.runId(),key(),request)).code);assertTrue(entered.await(5,TimeUnit.SECONDS));reconfigure(run,config(.55));release.countDown();assertEquals("EXECUTION_REVISION_STALE",result.get(10,TimeUnit.SECONDS));}finally{release.countDown();}base.error("EXECUTION_NOT_ALLOWED",()->runs.completeStep(student,run.runId(),"a5-evaluate",key(),new RunDtos.Revision(request.inputRevision())));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_execution_record e JOIN mp_experience_run r ON r.id=e.experience_run_id WHERE r.student_id=? AND e.status='SUCCEEDED'",Integer.class,student.internalId()));}
    @Test void previewClosesToInternalEvidenceOnlyAndLeaseTakeoverFencesOldWorker(){var closed=close(toReflection(toEvaluation(preview())));assertEquals("NOT_APPLICABLE",closed.reportStatus());assertEquals(0,count("mp_report"));assertEquals(0,count("mp_recommendation"));var first=jobs.claim("test-old");assertNotNull(first);var items=jobs.build(first);db.update("UPDATE mp_background_job SET lease_until=UTC_TIMESTAMP(3)-INTERVAL 1 SECOND WHERE id=?",first.job());var second=new EvidenceJobs(runs,closure).claim("test-new");assertNotNull(second);assertFalse(jobs.publish(first,items));assertFalse(jobs.heartbeat(first));assertTrue(jobs.publish(second,jobs.build(second)));assertEquals(List.of("FAILED","READY"),db.queryForList("SELECT status FROM mp_evidence_snapshot WHERE student_id=? ORDER BY snapshot_version_no",String.class,student.internalId()));assertTrue(new MajorCatalog(db).dashboard(student.internalId()).stream().allMatch(m->m.get("status").equals("NOT_STARTED")));}
