    @Test void formalClosureFreezesProfileAndCreatesNextPendingReportAndJobAtomically(){var run=toReflection(toEvaluation(formal()));long original=store.owned(student,run.runId()).profileId();db.update("INSERT INTO mp_decision_profile(public_id,student_id,profile_version_no,questionnaire_version,status,submitted_at,profile_summary_json) VALUES(?,?,2,'decision-profile-v1','CLAIMED',UTC_TIMESTAMP(3),'{\"newer\":true}')",PublicIds.next(),student.internalId());var closed=close(run);assertEquals("PENDING",closed.reportStatus());var next=db.queryForMap("SELECT decision_profile_id,primary_major_code,tie_break_rule FROM mp_recommendation WHERE student_id=? AND recommendation_type='NEXT'",student.internalId());assertEquals(original,((Number)next.get("decision_profile_id")).longValue());assertEquals("DATA_SCIENCE",next.get("primary_major_code"));assertEquals("EXPLICIT_NEXT_STYLE",next.get("tie_break_rule"));var lease=jobs.claim("test-formal");jobs.process(lease);assertEquals("READY",db.queryForObject("SELECT status FROM mp_evidence_snapshot WHERE id=?",String.class,lease.snapshot()));assertEquals("PENDING",runs.get(student,run.runId()).reportStatus());}
    @Test void closureFailureRollsBackReflectionNextAndReport(){var run=toReflection(toEvaluation(formal()));var failing=new ClosurePipeline(runs){@Override void enqueue(RunStore.Row row,JsonNode answers){super.enqueue(row,answers);throw new IllegalStateException("synthetic failure after complete close graph");}};var failingReflection=new ReflectionService(runs,failing);var view=reflection.get(student,run.runId());var input=new RunDtos.ReflectionSave(view.revision(),view.questionSetVersion(),value(view.definition().path("inputSchema"),0));assertThrows(IllegalStateException.class,()->failingReflection.submit(student,run.runId(),key(),input));assertEquals("TASK_COMPLETED",current(run).status());assertEquals("DRAFT",reflection.get(student,run.runId()).status());assertEquals(0,count("mp_report"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_recommendation WHERE student_id=? AND recommendation_type='NEXT'",Integer.class,student.internalId()));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_background_job WHERE owner_student_id=?",Integer.class,student.internalId()));}
    @Test void corruptedFrozenSourceRetriesAppendVersionsThenFailsWithoutReportReady(){var run=close(toReflection(toEvaluation(formal())));var lease=jobs.claim("test-retry-1");db.update("UPDATE mp_reflection SET draft_json=JSON_SET(draft_json,'$.continueSimilarWork','NO') WHERE experience_run_id=?",lease.run());for(int i=0;i<3;i++){jobs.process(lease);if(i<2){db.update("UPDATE mp_background_job SET available_at=UTC_TIMESTAMP(3) WHERE id=?",lease.job());lease=jobs.claim("test-retry-"+(i+2));assertNotNull(lease);}}assertEquals(List.of("FAILED","FAILED","FAILED"),db.queryForList("SELECT status FROM mp_evidence_snapshot WHERE student_id=? ORDER BY snapshot_version_no",String.class,student.internalId()));assertEquals("FAILED",current(run).reportStatus());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_evidence_item i JOIN mp_evidence_snapshot s ON s.id=i.evidence_snapshot_id WHERE s.student_id=?",Integer.class,student.internalId()));}
