    @Test void maliciousStudentAnalysisPersistsWithoutFactClaimPermissionAndFrozenRuleIsEndToEnd(){
        var run=toEvaluation(preview());String claim="调整阈值证明学习效果提升完全由模型造成，今后准确率一定提高";
        var configuration=config(.55);configuration.put("expectedEffect",claim);reconfigure(run,configuration);
        var answer=(ObjectNode)value(definition("a5-evaluate").path("inputSchema"),0);answer.put("comparisonNotes",claim);save(run,"a5-evaluate",answer);
        execute.execute(student,run.runId(),key(),request(run));run=runs.completeStep(student,run.runId(),"a5-evaluate",key(),new RunDtos.Revision(runs.step(student,run.runId(),"a5-evaluate").revision()));
        run=complete(run,"a6-decision",value(definition("a6-decision").path("inputSchema"),0));close(runs.taskComplete(student,run.runId(),key(),new RunDtos.Revision(run.revision())));
        var frozen=store.node(db.queryForObject("SELECT closed_input_manifest_json FROM mp_experience_run WHERE public_id=?",String.class,run.runId()));
        assertEquals("closed-input-v3",frozen.path("schemaVersion").asText());assertEquals("evidence-v2",frozen.path("evidenceRuleVersion").asText());
        var lease=jobs.claim("test-analysis");assertEquals("evidence-v2",lease.rule());jobs.process(lease);
        var snapshot=db.queryForMap("SELECT status,evidence_rule_version FROM mp_evidence_snapshot WHERE id=?",lease.snapshot());assertEquals("READY",snapshot.get("status"));assertEquals("evidence-v2",snapshot.get("evidence_rule_version"));
        assertEquals("evidence-v2",store.node(db.queryForObject("SELECT checkpoint_json FROM mp_background_job WHERE id=?",String.class,lease.job())).path("evidenceRuleVersion").asText());
        var items=db.queryForList("SELECT evidence_type,structured_value_json,allowed_claim_types_json,rule_version FROM mp_evidence_item WHERE evidence_snapshot_id=?",lease.snapshot());int preserved=0;
        for(var item:items){assertEquals("evidence-v2",item.get("rule_version"));var value=store.node(item.get("structured_value_json"));var allowed=store.node(item.get("allowed_claim_types_json"));
            if(value.toString().contains(claim)){preserved++;assertEquals("STUDENT_ANALYSIS",item.get("evidence_type"));assertTrue(allowed.isEmpty());assertEquals("UNVERIFIED",value.path("verificationStatus").asText());}
            if(allowed.toString().contains("OBSERVED_FACT"))assertFalse(value.toString().contains(claim));
        }assertEquals(2,preserved);
    }
    @Test void sourceAndProfileRemainFrozenWhenNewerRowsExistAfterClose(){
        var run=close(toReflection(toEvaluation(preview())));long runId=store.owned(student,run.runId()).id();long profile=store.owned(student,run.runId()).profileId();
        var state=db.queryForMap("SELECT id,current_revision FROM mp_step_state WHERE experience_run_id=? AND step_key='a5-evaluate'",runId);long stateId=((Number)state.get("id")).longValue(),newRevision=((Number)state.get("current_revision")).longValue()+1;
        var later=mapper.createObjectNode().put("comparisonNotes","NEWER_ANSWER_MUST_NOT_REPLACE_FROZEN_SOURCE").put("tradeoff","后来追加的解释");
        db.update("INSERT INTO mp_step_response_revision(step_state_id,revision_no,response_schema_version,response_json,content_sha256) VALUES(?,?,'ai-response-v1',?,?)",stateId,newRevision,store.json(later),store.hash(later));
        db.update("UPDATE mp_step_state SET current_revision=? WHERE id=?",newRevision,stateId);
        db.update("INSERT INTO mp_decision_profile(public_id,student_id,profile_version_no,questionnaire_version,status,submitted_at,profile_summary_json) VALUES(?,?,2,'decision-profile-v1','CLAIMED',UTC_TIMESTAMP(3),'{\"newer\":true}')",PublicIds.next(),student.internalId());
        var lease=jobs.claim("test-pinned-source");var items=jobs.build(lease);assertFalse(store.json(items).contains("NEWER_ANSWER"));assertTrue(jobs.publish(lease,items));
        assertEquals(profile,db.queryForObject("SELECT decision_profile_id FROM mp_evidence_snapshot WHERE id=?",Long.class,lease.snapshot()));
        var analysis=items.stream().filter(i->i.key().equals("analysis:a5-evaluate")).findFirst().orElseThrow();assertEquals("合成技术验证回答0",analysis.value().path("answers").path("comparisonNotes").asText());
    }
    void replaceFrozenForCompatibilityFixture(String runPublicId,ObjectNode manifest){
        long id=store.owned(student,runPublicId).id();String sha=store.hash(manifest),rule=ClosurePipeline.frozenRule(manifest);
        db.update("UPDATE mp_experience_run SET closed_input_manifest_json=?,closed_input_sha256=? WHERE id=?",store.json(manifest),sha,id);
        db.update("UPDATE mp_run_closure_request SET closed_input_sha256=? WHERE experience_run_id=?",sha,id);
        db.update("UPDATE mp_background_job SET business_key=?,checkpoint_json=NULL WHERE target_id=? AND owner_student_id=?",ClosurePipeline.evidenceKey(runPublicId,sha,rule),id,student.internalId());
    }
    @Test void unsupportedLegacyRuleFailsExplicitlyWithoutReinterpretingAsCurrent(){assertUnsupportedRule("evidence-v1");}
    @Test void unsupportedFutureRuleFailsExplicitlyWithoutReinterpretingAsCurrent(){assertUnsupportedRule("evidence-v99");}
    void assertUnsupportedRule(String rule){
            var run=close(toReflection(toEvaluation(preview())));var frozen=(ObjectNode)store.node(db.queryForObject("SELECT closed_input_manifest_json FROM mp_experience_run WHERE public_id=?",String.class,run.runId()));
            if(rule.equals("evidence-v1")){frozen.put("schemaVersion","closed-input-v2");frozen.remove("evidenceRuleVersion");}else frozen.put("evidenceRuleVersion",rule);
            replaceFrozenForCompatibilityFixture(run.runId(),frozen);var lease=jobs.claim("test-unsupported");assertEquals(rule,lease.rule());jobs.process(lease);
            var snapshot=db.queryForMap("SELECT status,evidence_rule_version,failure_code FROM mp_evidence_snapshot WHERE id=?",lease.snapshot());assertEquals("FAILED",snapshot.get("status"));assertEquals(rule,snapshot.get("evidence_rule_version"));assertEquals("EVIDENCE_RULE_UNSUPPORTED",snapshot.get("failure_code"));
            assertEquals("FAILED",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,lease.job()));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_evidence_item WHERE evidence_snapshot_id=?",Integer.class,lease.snapshot()));
    }
    @Test void readyLegacySnapshotIsNotRewrittenOrRepublished(){
        var run=close(toReflection(toEvaluation(preview())));var lease=jobs.claim("test-ready");var items=jobs.build(lease);assertTrue(jobs.publish(lease,items));
        db.update("UPDATE mp_evidence_snapshot SET evidence_rule_version='evidence-v1' WHERE id=?",lease.snapshot());db.update("UPDATE mp_evidence_item SET rule_version='evidence-v1' WHERE evidence_snapshot_id=?",lease.snapshot());
        var before=db.queryForMap("SELECT * FROM mp_evidence_snapshot WHERE id=?",lease.snapshot());var itemBefore=db.queryForList("SELECT * FROM mp_evidence_item WHERE evidence_snapshot_id=? ORDER BY id",lease.snapshot());
        assertNull(jobs.claim("test-no-legacy-rebuild"));assertFalse(jobs.publish(lease,items));assertEquals(before,db.queryForMap("SELECT * FROM mp_evidence_snapshot WHERE id=?",lease.snapshot()));assertEquals(itemBefore,db.queryForList("SELECT * FROM mp_evidence_item WHERE evidence_snapshot_id=? ORDER BY id",lease.snapshot()));
    }
